//! The Settings editor's data: every setting VS Code registers
//! (`assets/settings/settings.json`, generated by `tools/settings-schema.mjs`
//! from a dump of 1.145.2), the table of contents (settingsLayout.ts
//! `tocData`), how settings are placed in it (settingsTree.ts
//! `resolveSettingsTree` / `createTocTreeForExtensionSettings`), their
//! labels (settingsTreeModels.ts `settingKeyToDisplayFormat`) and search.

use std::cmp::Ordering;
use std::collections::HashSet;
use std::sync::OnceLock;

use regex::Regex;
use serde::Deserialize;
use serde_json::Value;

const SCHEMA: &str = include_str!("../../../assets/settings/settings.json");

/// How a setting is edited (settingsTreeModels.ts `SettingValueType`).
#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "camelCase")]
pub enum ValueType {
    Enum,
    String,
    MultilineString,
    Exclude,
    Include,
    Integer,
    Number,
    Boolean,
    Array,
    NullableInteger,
    NullableNumber,
    BooleanObject,
    Object,
    ComplexObject,
    LanguageTag,
    Complex,
}

#[derive(Clone, Debug, Default, Deserialize)]
pub struct Section {
    #[serde(default)]
    pub id: String,
    #[serde(default)]
    pub title: String,
    pub order: Option<f64>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Source {
    pub id: String,
    pub display_name: Option<String>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SettingDef {
    pub key: String,
    pub value_type: ValueType,
    #[serde(default)]
    pub default: Value,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub markdown: bool,
    #[serde(default, rename = "enum")]
    pub enum_values: Vec<Value>,
    #[serde(default)]
    pub enum_descriptions: Vec<Option<String>>,
    #[serde(default)]
    pub enum_markdown: bool,
    #[serde(default)]
    pub enum_item_labels: Vec<Option<String>>,
    pub array_item_type: Option<String>,
    pub minimum: Option<f64>,
    pub maximum: Option<f64>,
    #[serde(default)]
    pub tags: Vec<String>,
    #[serde(default)]
    pub keywords: Vec<String>,
    pub scope: Option<u8>,
    pub order: Option<f64>,
    pub title: Option<String>,
    #[serde(default)]
    pub restricted: bool,
    pub deprecation: Option<String>,
    #[serde(default)]
    pub deprecation_markdown: bool,
    #[serde(default)]
    pub deprecation_show_in_settings: bool,
    /// For objects whose keys are all booleans: key → description.
    #[serde(default)]
    pub properties: serde_json::Map<String, Value>,
    #[serde(default)]
    pub section: Section,
    pub source: Option<Source>,
}

impl SettingDef {
    pub fn has_tag(&self, tag: &str) -> bool {
        self.tags.iter().any(|t| t == tag)
    }

    /// The label of enum value `i` in the dropdown.
    pub fn enum_label(&self, i: usize) -> String {
        if let Some(Some(l)) = self.enum_item_labels.get(i) {
            return l.clone();
        }
        match self.enum_values.get(i) {
            Some(Value::String(s)) => s.clone(),
            Some(Value::Null) => "null".into(),
            Some(v) => v.to_string(),
            None => String::new(),
        }
    }

    pub fn enum_description(&self, i: usize) -> Option<&str> {
        self.enum_descriptions.get(i).and_then(|d| d.as_deref()).filter(|d| !d.is_empty())
    }
}

/// Every setting, in registration order.
pub fn settings() -> &'static [SettingDef] {
    static ALL: OnceLock<Vec<SettingDef>> = OnceLock::new();
    ALL.get_or_init(|| serde_json::from_str(SCHEMA).expect("assets/settings/settings.json"))
}

pub fn find(key: &str) -> Option<usize> {
    settings().iter().position(|s| s.key == key)
}

