struct Toc {
    id: &'static str,
    label: &'static str,
    settings: &'static [&'static str],
    children: &'static [Toc],
    hide: bool,
}

const fn leaf(id: &'static str, label: &'static str, settings: &'static [&'static str]) -> Toc {
    Toc { id, label, settings, children: &[], hide: false }
}

