/// A node of the resolved tree: a group with settings and/or sub-groups.
#[derive(Clone, Debug, Default)]
pub struct TocNode {
    pub id: String,
    pub label: String,
    /// Indexes into `settings()`.
    pub settings: Vec<usize>,
    pub children: Vec<TocNode>,
}

impl TocNode {
    /// Settings in this node and below.
    pub fn count(&self) -> usize {
        self.settings.len() + self.children.iter().map(TocNode::count).sum::<usize>()
    }
}

/// `createSettingMatchRegExp`: `*` is any text, the rest literal, any case.
fn pattern_matches(pattern: &str, key: &str) -> bool {
    fn go(p: &[u8], k: &[u8]) -> bool {
        match p.split_first() {
            None => k.is_empty(),
            Some((b'*', rest)) => (0..=k.len()).any(|i| go(rest, &k[i..])),
            Some((c, rest)) => k.first().is_some_and(|kc| kc.eq_ignore_ascii_case(c)) && go(rest, &k[1..]),
        }
    }
    go(pattern.as_bytes(), key.as_bytes())
}

fn compare_nullable(a: Option<f64>, b: Option<f64>) -> Ordering {
    let a = a.unwrap_or(f64::MAX);
    let b = b.unwrap_or(f64::MAX);
    a.partial_cmp(&b).unwrap_or(Ordering::Equal)
}

/// `String.prototype.localeCompare` for setting keys and labels (ICU root
/// collation, simplified): punctuation before digits before letters,
/// letters case-insensitive first.
pub fn locale_compare(a: &str, b: &str) -> Ordering {
    // ICU root (DUCET) order of ASCII punctuation and symbols.
    const PUNCT: &str = "_-,;:!?.'\"()[]{}@*/\\&#%`^+<=>|~$";
    let key = |s: &str| -> Vec<(u8, u32)> {
        s.chars()
            .map(|c| {
                if c.is_whitespace() {
                    (0, 0)
                } else if let Some(i) = PUNCT.find(c) {
                    (1, i as u32)
                } else if c.is_ascii_punctuation() {
                    (1, 100 + c as u32)
                } else if c.is_numeric() {
                    (2, c as u32)
                } else {
                    (3, c.to_lowercase().next().unwrap_or(c) as u32)
                }
            })
            .collect()
    };
    key(a).cmp(&key(b)).then_with(|| b.cmp(a))
}

/// `sortSettings`: preview and experimental settings last; within a tier by
/// `order`, then key.
fn sort_settings(list: &mut [usize]) {
    let all = settings();
    let tier = |s: &SettingDef| {
        if s.has_tag("experimental") {
            2
        } else if s.has_tag("preview") {
            1
        } else {
            0
        }
    };
    list.sort_by(|&a, &b| {
        let (a, b) = (&all[a], &all[b]);
        tier(a).cmp(&tier(b)).then_with(|| compare_nullable(a.order, b.order)).then_with(|| locale_compare(&a.key, &b.key))
    });
}

/// Takes the settings a node's patterns match out of `pool` (except the
/// multi-group ones), like `getMatchingSettings`.
fn take_matching(pool: &mut Vec<usize>, patterns: &[&str], visible: &dyn Fn(usize) -> bool) -> Vec<usize> {
    let all = settings();
    let mut out = Vec::new();
    pool.retain(|&i| {
        let s = &all[i];
        let hit = patterns.iter().any(|p| match p.strip_prefix("@tag:") {
            Some(tag) => s.has_tag(tag),
            None => pattern_matches(p, &s.key),
        });
        if hit && visible(i) {
            out.push(i);
            return MULTI_GROUP.contains(&s.key.as_str());
        }
        true
    });
    sort_settings(&mut out);
    out
}

fn resolve(spec: &Toc, pool: &mut Vec<usize>, visible: &dyn Fn(usize) -> bool) -> TocNode {
    let children = spec
        .children
        .iter()
        .filter(|c| !c.hide)
        .map(|c| resolve(c, pool, visible))
        .filter(|c| !c.children.is_empty() || !c.settings.is_empty())
        .collect();
    let settings = take_matching(pool, spec.settings, visible);
    TocNode { id: spec.id.into(), label: spec.label.into(), settings, children }
}

/// Extension settings, one entry per extension under "Extensions".
fn extension_tree(visible: &dyn Fn(usize) -> bool) -> TocNode {
    struct Group {
        ext: String,
        ext_name: String,
        id: String,
        title: String,
        order: Option<f64>,
        settings: Vec<usize>,
    }
    let mut groups: Vec<Group> = Vec::new();
    for (i, s) in settings().iter().enumerate() {
        let Some(src) = &s.source else { continue };
        let pos = groups.iter().position(|g| {
            g.ext == src.id && if s.section.title.is_empty() { g.id == s.section.id && g.title.is_empty() } else { g.title == s.section.title }
        });
        let g = match pos {
            Some(p) => &mut groups[p],
            None => {
                groups.push(Group {
                    ext: src.id.clone(),
                    ext_name: src.display_name.clone().unwrap_or_else(|| src.id.clone()),
                    id: s.section.id.clone(),
                    title: s.section.title.clone(),
                    order: s.section.order,
                    settings: Vec::new(),
                });
                groups.last_mut().unwrap()
            }
        };
        if visible(i) {
            g.settings.push(i);
        }
    }
    // extension id → (name, children)
    let mut exts: Vec<(String, String, Vec<(TocNode, Option<f64>)>)> = Vec::new();
    for mut g in groups {
        sort_settings(&mut g.settings);
        let id = if !g.id.is_empty() && g.id != g.ext { g.id.clone() } else { g.title.clone() };
        let child = TocNode { id, label: g.title.clone(), settings: g.settings, children: Vec::new() };
        match exts.iter_mut().find(|(e, ..)| *e == g.ext) {
            Some((.., children)) => children.push((child, g.order)),
            None => exts.push((g.ext.clone(), g.ext_name.clone(), vec![(child, g.order)])),
        }
    }
    let mut out = Vec::new();
    for (ext, name, mut children) in exts {
        if children.len() == 1 {
            let (c, _) = children.pop().unwrap();
            out.push(TocNode { id: ext, label: c.label, settings: c.settings, children: Vec::new() });
            continue;
        }
        children.sort_by(|a, b| compare_nullable(a.1, b.1));
        let mut children: Vec<TocNode> = children.into_iter().map(|(c, _)| c).collect();
        if let Some(p) = children.iter().position(|c| c.label == name) {
            let ungrouped = children.remove(p);
            out.push(TocNode { id: ext, label: name, settings: ungrouped.settings, children });
        } else {
            out.push(TocNode { id: ext, label: name, settings: Vec::new(), children });
        }
    }
    // Groups left empty by a filter disappear.
    for node in &mut out {
        node.children.retain(|c| c.count() > 0);
    }
    out.retain(|n| n.count() > 0);
    out.sort_by(|a, b| locale_compare(&a.label, &b.label));
    TocNode { id: "extensions".into(), label: "Extensions".into(), settings: Vec::new(), children: out }
}

/// The whole tree: Commonly Used, the core groups, then Extensions.
/// `visible` filters settings (advanced settings, search).
pub fn build_tree(visible: &dyn Fn(usize) -> bool) -> TocNode {
    let all = settings();
    let mut pool: Vec<usize> = (0..all.len()).filter(|&i| all[i].source.is_none()).collect();
    let mut children: Vec<TocNode> = TOC
        .iter()
        .filter(|t| !t.hide)
        .map(|t| resolve(t, &mut pool, visible))
        .filter(|c| !c.children.is_empty() || !c.settings.is_empty())
        .collect();
    let commonly: Vec<usize> = COMMONLY_USED.iter().filter_map(|k| find(k)).filter(|&i| visible(i)).collect();
    children.insert(0, TocNode { id: "commonlyUsed".into(), label: "Commonly Used".into(), settings: commonly, children: Vec::new() });
    children.push(extension_tree(visible));
    TocNode { id: "root".into(), label: "root".into(), settings: Vec::new(), children }
}

// ── Labels ────────────────────────────────────────────────────────────────

fn regex(cell: &'static OnceLock<Regex>, re: &str) -> &'static Regex {
    cell.get_or_init(|| Regex::new(re).unwrap())
}

/// `wordifyKey`: `editor.fontSize` → `Editor › Font Size`.
pub fn wordify_key(key: &str) -> String {
    static DOT: OnceLock<Regex> = OnceLock::new();
    static CAMEL: OnceLock<Regex> = OnceLock::new();
    static CAPS: OnceLock<Regex> = OnceLock::new();
    static WORD: OnceLock<Regex> = OnceLock::new();
    const ACRONYMS: &[&str] = &["css", "html", "scss", "less", "json", "js", "ts", "ie", "id", "php", "scm"];
    const TERMS: &[(&str, &str)] = &[
        ("power shell", "PowerShell"),
        ("powershell", "PowerShell"),
        ("javascript", "JavaScript"),
        ("typescript", "TypeScript"),
        ("github", "GitHub"),
        ("ocaml", "OCaml"),
        ("jet brains", "JetBrains"),
        ("jetbrains", "JetBrains"),
        ("re sharper", "ReSharper"),
        ("resharper", "ReSharper"),
    ];
    let s = regex(&DOT, r"\.([a-z0-9])").replace_all(key, |c: &regex::Captures| format!(" \u{203A} {}", c[1].to_uppercase()));
    let s = regex(&CAMEL, r"([a-z0-9])([A-Z])").replace_all(&s, "$1 $2");
    let s = regex(&CAPS, r"([A-Z]+)([A-Z][a-z])").replace_all(&s, "$1 $2");
    let mut s = s.into_owned();
    if let Some(first) = s.chars().next().filter(|c| c.is_ascii_lowercase()) {
        s.replace_range(..1, &first.to_ascii_uppercase().to_string());
    }
    let mut s = regex(&WORD, r"\b\w+\b")
        .replace_all(&s, |c: &regex::Captures| {
            let w = &c[0];
            if ACRONYMS.contains(&w.to_lowercase().as_str()) {
                w.to_uppercase()
            } else {
                w.to_string()
            }
        })
        .into_owned();
    static TERM_RES: OnceLock<Vec<(Regex, &'static str)>> = OnceLock::new();
    let terms = TERM_RES.get_or_init(|| TERMS.iter().map(|(from, to)| (Regex::new(&format!(r"(?i)\b{}\b", regex::escape(from))).unwrap(), *to)).collect());
    for (re, to) in terms {
        if re.is_match(&s) {
            s = re.replace_all(&s, *to).into_owned();
        }
    }
    s
}

/// `trimCategoryForGroup`: drops the part of a category its group already
/// says.
fn trim_category(category: &str, group_id: &str) -> String {
    // `^parts.join('\.')(\.|$)`, any case: the prefix and what's left.
    fn strip<'a>(category: &'a str, prefix: &str) -> Option<&'a str> {
        let head = category.get(..prefix.len())?;
        if !head.eq_ignore_ascii_case(prefix) {
            return None;
        }
        let rest = &category[prefix.len()..];
        if rest.is_empty() {
            Some(rest)
        } else {
            rest.strip_prefix('.')
        }
    }
    let do_trim = |forward: bool| -> Option<String> {
        let mut group = group_id.to_string();
        if !category.to_lowercase().ends_with("insiders") {
            let lower = group.to_lowercase();
            if lower.ends_with("-insiders") {
                group.truncate(group.len() - "-insiders".len());
            } else if lower.ends_with("insiders") {
                group.truncate(group.len() - "insiders".len());
            }
        }
        let mut parts: Vec<String> = group
            .split('.')
            .map(|p| if p.replace('-', "").eq_ignore_ascii_case(category) { p.replace('-', "") } else { p.to_string() })
            .collect();
        while !parts.is_empty() {
            if let Some(rest) = strip(category, &parts.join(".")) {
                return Some(rest.to_string());
            }
            if forward {
                parts.pop();
            } else {
                parts.remove(0);
            }
        }
        None
    };
    do_trim(true).or_else(|| do_trim(false)).unwrap_or_else(|| category.to_string())
}

/// `settingKeyToDisplayFormat`: (category, label) shown as "Category: Label"
/// in the group with id `group_id`.
pub fn display_format(setting: &SettingDef, group_id: &str) -> (String, String) {
    if let Some(title) = &setting.title {
        // `categoryLabel` for titled settings: the section id unless it is
        // the extension itself.
        let ext = setting.source.as_ref().map(|s| s.id.as_str());
        let category = if ext == Some(setting.section.id.as_str()) { String::new() } else { setting.section.id.clone() };
        return (category, title.clone());
    }
    let key = setting.key.as_str();
    let (category, name) = match key.rfind('.') {
        Some(i) => (&key[..i], &key[i + 1..]),
        None => ("", key),
    };
    let group = group_id.replace('/', ".");
    let category = wordify_key(&trim_category(category, &group));
    (category, wordify_key(name))
}

// ── Search ────────────────────────────────────────────────────────────────

/// What the search box asks for: `@` filters plus text
/// (settingsEditor2.ts `parseQuery`).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Query {
    /// The text without filters, cleaned like `cleanFilter`.
    pub text: String,
    pub modified: bool,
    pub tags: Vec<String>,
    pub ids: Vec<String>,
    pub extensions: Vec<String>,
    pub features: Vec<String>,
}

/// `SettingMatchType` (preferences.ts): bigger is better.
pub mod match_type {
    pub const LANGUAGE_TAG: u32 = 1 << 0;
    pub const NON_CONTIGUOUS_QUERY_IN_ID: u32 = 1 << 2;
    pub const DESCRIPTION_OR_VALUE: u32 = 1 << 3;
    pub const NON_CONTIGUOUS_WORDS_IN_LABEL: u32 = 1 << 4;
    pub const CONTIGUOUS_WORDS_IN_LABEL: u32 = 1 << 5;
    pub const CONTIGUOUS_QUERY_IN_ID: u32 = 1 << 6;
    pub const ALL_WORDS_IN_LABEL: u32 = 1 << 7;
    pub const EXACT: u32 = 1 << 8;
    pub const KEY_TYPES: u32 = ALL_WORDS_IN_LABEL | CONTIGUOUS_WORDS_IN_LABEL | NON_CONTIGUOUS_WORDS_IN_LABEL | NON_CONTIGUOUS_QUERY_IN_ID | CONTIGUOUS_QUERY_IN_ID;
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SettingMatch {
    pub match_type: u32,
    pub key_score: usize,
}

fn is_separator(c: char) -> bool {
    c.is_whitespace() || "()[]{}<>`'\"-/;:,.?!".contains(c)
}

/// filters.ts `nextWord`.
fn next_word(t: &[char], start: usize) -> usize {
    (start..t.len()).find(|&i| is_separator(t[i]) || (i > 0 && is_separator(t[i - 1]))).unwrap_or(t.len())
}

/// filters.ts `matchesWords`: the word's characters at word starts of the
/// target (only consecutive ones when `contiguous`), separators matching
/// each other.
pub fn matches_words(word: &str, target: &str, contiguous: bool) -> bool {
    let w: Vec<char> = word.to_lowercase().chars().collect();
    let t: Vec<char> = target.to_lowercase().chars().collect();
    if t.is_empty() {
        return false;
    }
    fn go(w: &[char], t: &[char], wi: usize, ti: usize, contiguous: bool, memo: &mut HashSet<(usize, usize)>) -> bool {
        if wi == w.len() {
            return true;
        }
        if ti == t.len() || memo.contains(&(wi, ti)) {
            return false;
        }
        let ok = (w[wi] == t[ti] || (is_separator(w[wi]) && is_separator(t[ti]))) && {
            let mut next = ti + 1;
            let mut found = go(w, t, wi + 1, next, contiguous, memo);
            if !contiguous {
                while !found {
                    next = next_word(t, next);
                    if next >= t.len() {
                        break;
                    }
                    found = go(w, t, wi + 1, next, contiguous, memo);
                    next += 1;
                }
            }
            found
        };
        if !ok {
            memo.insert((wi, ti));
        }
        ok
    }
    let mut memo = HashSet::new();
    let mut ti = 0;
    while ti < t.len() {
        if go(&w, &t, 0, ti, contiguous, &mut memo) {
            return true;
        }
        ti = next_word(&t, ti + 1);
    }
    false
}

/// `SettingMatches._keyToLabel`: `editor.formatOnSave` → `editor format on save`.
fn key_to_label(key: &str) -> String {
    static CAMEL: OnceLock<Regex> = OnceLock::new();
    static LETTER_DIGIT: OnceLock<Regex> = OnceLock::new();
    static DIGIT_LETTER: OnceLock<Regex> = OnceLock::new();
    let s: String = key.chars().map(|c| if matches!(c, '-' | '.' | '_') { ' ' } else { c }).collect();
    let s = regex(&CAMEL, r"([a-z]+)([A-Z])").replace_all(&s, "$1 $2");
    let s = regex(&LETTER_DIGIT, r"([A-Za-z]+)(\d+)").replace_all(&s, "$1 $2");
    let s = regex(&DIGIT_LETTER, r"(\d+)([A-Za-z]+)").replace_all(&s, "$1 $2");
    s.to_lowercase()
}

fn alphanumeric(s: &str) -> String {
    s.chars().filter(|c| c.is_alphanumeric()).collect::<String>().to_lowercase()
}

fn is_subsequence(word: &str, target: &str) -> bool {
    let mut t = target.chars();
    word.chars().all(|c| t.any(|x| x == c))
}

/// preferencesSearch.ts `SettingMatches` (with the description searched):
/// how well `text` matches a setting, if at all.
pub fn setting_match(text: &str, s: &SettingDef) -> Option<SettingMatch> {
    use match_type::*;
    let words: Vec<&str> = {
        let mut seen = Vec::new();
        for w in text.split(' ') {
            if !seen.contains(&w) {
                seen.push(w);
            }
        }
        seen
    };
    let label = key_to_label(&s.key);
    let mut mt = 0;
    let mut score = 0;
    let key_words = words.iter().filter(|w| matches_words(w, &label, true)).count();
    if key_words == words.len() {
        mt |= ALL_WORDS_IN_LABEL;
    } else if key_words >= 2 {
        mt |= CONTIGUOUS_WORDS_IN_LABEL;
        score = key_words;
    }
    let (q_alnum, key_alnum) = (alphanumeric(text), alphanumeric(&s.key));
    if q_alnum.len() <= key_alnum.len() && key_alnum.contains(&q_alnum) {
        mt |= CONTIGUOUS_QUERY_IN_ID;
    }
    if mt == 0 {
        let key_words = words.iter().filter(|w| matches_words(w, &label, false)).count();
        if key_words >= 2 || (key_words == 1 && words.len() == 1) {
            mt |= NON_CONTIGUOUS_WORDS_IN_LABEL;
            score = key_words;
        } else if q_alnum.len() <= key_alnum.len() && is_subsequence(&q_alnum, &key_alnum) {
            mt |= NON_CONTIGUOUS_QUERY_IN_ID;
        }
    }
    if mt < CONTIGUOUS_WORDS_IN_LABEL {
        // Every word somewhere in the description (or keywords).
        let mut lines: Vec<String> = s.description.split('\n').map(str::to_lowercase).collect();
        if !s.keywords.is_empty() {
            lines.push(s.keywords.join(" ").to_lowercase());
        }
        if words.iter().all(|w| lines.iter().any(|l| l.contains(&w.to_lowercase()))) {
            mt |= DESCRIPTION_OR_VALUE;
        }
        // Or every word in one of the enum's string values.
        if s.enum_values.iter().filter_map(Value::as_str).any(|o| words.iter().all(|w| o.to_lowercase().contains(&w.to_lowercase()))) {
            mt |= DESCRIPTION_OR_VALUE;
        }
    }
    if mt == 0 {
        return None;
    }
    if text.eq_ignore_ascii_case(&s.key) {
        mt = EXACT;
    }
    Some(SettingMatch { match_type: mt, key_score: score })
}

impl Query {
    pub fn parse(text: &str) -> Query {
        let mut q = Query::default();
        let mut rest = Vec::new();
        for token in text.split_whitespace() {
            if token == "@modified" {
                q.modified = true;
            } else if let Some(t) = token.strip_prefix("@tag:") {
                q.tags.push(t.to_lowercase());
            } else if let Some(t) = token.strip_prefix("@id:") {
                q.ids.extend(t.split(',').filter(|s| !s.is_empty()).map(str::to_string));
            } else if let Some(t) = token.strip_prefix("@ext:") {
                q.extensions.push(t.to_lowercase());
            } else if let Some(t) = token.strip_prefix("@feature:") {
                q.features.push(t.to_lowercase());
            } else {
                rest.push(token);
            }
        }
        // `cleanFilter`: `"` and `:` (pasted with setting names) are spaces.
        let cleaned: String = rest.join(" ").chars().map(|c| if c == '"' || c == ':' { ' ' } else { c }).collect();
        q.text = cleaned.replace("  ", " ").trim().to_string();
        q
    }

    pub fn is_empty(&self) -> bool {
        *self == Query::default()
    }

    /// The `@` filters only.
    pub fn passes_filters(&self, i: usize, configured: &dyn Fn(&str) -> bool) -> bool {
        let s = &settings()[i];
        if self.modified && !configured(&s.key) {
            return false;
        }
        // `requireTrustedWorkspace` is every restricted setting.
        if !self.tags.iter().all(|t| s.tags.iter().any(|st| st.to_lowercase() == *t) || (t == "requiretrustedworkspace" && s.restricted)) {
            return false;
        }
        if !self.ids.is_empty() && !self.ids.iter().any(|id| *id == s.key) {
            return false;
        }
        if !self.extensions.is_empty() && !s.source.as_ref().is_some_and(|src| self.extensions.iter().any(|e| src.id.to_lowercase() == *e)) {
            return false;
        }
        if !self.features.is_empty() && !self.features.iter().any(|f| s.key.to_lowercase().starts_with(&format!("{f}."))) {
            return false;
        }
        true
    }

    /// Filters and text together (no ranking).
    pub fn matches(&self, i: usize, configured: &dyn Fn(&str) -> bool) -> bool {
        self.passes_filters(i, configured) && (self.text.is_empty() || setting_match(&self.text, &settings()[i]).is_some())
    }
}

/// `LocalSearchProvider.searchModel` + `SearchResultModel.sortResults`:
/// the settings (given in table-of-contents order) that answer the
/// query's text, best first.
pub fn rank(text: &str, toc_order: &[usize]) -> Vec<usize> {
    use match_type::*;
    if text.is_empty() {
        return toc_order.to_vec();
    }
    let all = settings();
    let matched: Vec<(usize, usize, SettingMatch)> =
        toc_order.iter().enumerate().filter_map(|(pos, &i)| setting_match(text, &all[i]).map(|m| (pos, i, m))).collect();
    let top = matched.iter().map(|(_, _, m)| m.match_type & KEY_TYPES).max().unwrap_or(0);
    let mut kept: Vec<(usize, usize, SettingMatch)> = matched
        .into_iter()
        .filter(|(_, _, m)| m.match_type & top != 0 || m.match_type & (DESCRIPTION_OR_VALUE | LANGUAGE_TAG) != 0 || m.match_type == EXACT)
        .collect();
    kept.sort_by(|a, b| {
        if a.2.match_type != b.2.match_type {
            b.2.match_type.cmp(&a.2.match_type)
        } else if a.2.match_type & (NON_CONTIGUOUS_WORDS_IN_LABEL | CONTIGUOUS_WORDS_IN_LABEL) != 0 {
            b.2.key_score.cmp(&a.2.key_score).then(a.0.cmp(&b.0))
        } else {
            a.0.cmp(&b.0)
        }
    });
    kept.into_iter().map(|(_, i, _)| i).collect()
}

/// Settings hidden unless asked for (`ADVANCED_SETTING_TAG`), and
/// deprecated ones (shown only when set).
pub fn hidden_by_default(i: usize, configured: &dyn Fn(&str) -> bool) -> bool {
    let s = &settings()[i];
    (s.has_tag("advanced")) || (s.deprecation.is_some() && !s.deprecation_show_in_settings && !configured(&s.key))
}

/// Settings that need a trusted workspace and could be set in one
/// (workspaceTrustEditor.ts: restricted, not application / machine
/// scoped, deprecated ones left out).
pub fn restricted_workspace_setting_count() -> usize {
    settings().iter().filter(|s| s.restricted && !matches!(s.scope, Some(1) | Some(2) | Some(3)) && s.deprecation.is_none()).count()
}

/// Keys of every setting (for tests and `@id:` completion).
pub fn keys() -> HashSet<&'static str> {
    settings().iter().map(|s| s.key.as_str()).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn schema_loads_with_value_types() {
        let all = settings();
        assert!(all.len() > 2000);
        let font = &all[find("editor.fontSize").unwrap()];
        assert_eq!(font.value_type, ValueType::Number);
        assert_eq!(font.default, serde_json::json!(12));
        assert_eq!(all[find("files.autoSave").unwrap()].value_type, ValueType::Enum);
        assert_eq!(all[find("files.exclude").unwrap()].value_type, ValueType::Exclude);
        assert_eq!(all[find("editor.formatOnSave").unwrap()].value_type, ValueType::Boolean);
    }

    #[test]
    fn labels_like_the_settings_editor() {
        assert_eq!(wordify_key("fontSize"), "Font Size");
        assert_eq!(wordify_key("editor.formatOnSave"), "Editor \u{203A} Format On Save");
        assert_eq!(wordify_key("typescript.preferences"), "TypeScript \u{203A} Preferences");
        assert_eq!(wordify_key("cssValidate"), "CSS Validate");
        let font = &settings()[find("editor.fontSize").unwrap()];
        assert_eq!(display_format(font, "commonlyUsed"), ("Editor".into(), "Font Size".into()));
        let cursor = &settings()[find("editor.cursorBlinking").unwrap()];
        assert_eq!(display_format(cursor, "editor/cursor"), ("".into(), "Cursor Blinking".into()));
        let minimap = &settings()[find("editor.minimap.enabled").unwrap()];
        assert_eq!(display_format(minimap, "editor/minimap"), ("".into(), "Enabled".into()));
        let git = &settings()[find("git.enabled").unwrap()];
        assert_eq!(display_format(git, "vscode.git"), ("".into(), "Enabled".into()));
    }

    #[test]
    fn tree_has_the_toc_of_the_settings_editor() {
        let tree = build_tree(&|i| !hidden_by_default(i, &|_| false));
        let labels: Vec<&str> = tree.children.iter().map(|c| c.label.as_str()).collect();
        assert_eq!(labels, ["Commonly Used", "Text Editor", "Workbench", "Window", "Chat", "Features", "Application", "Security", "Extensions"]);
        let commonly: Vec<&str> = tree.children[0].settings.iter().map(|&i| settings()[i].key.as_str()).collect();
        assert_eq!(&commonly[..3], ["editor.fontSize", "editor.formatOnSave", "files.autoSave"]);
        let editor = &tree.children[1];
        let subs: Vec<&str> = editor.children.iter().map(|c| c.label.as_str()).collect();
        assert_eq!(subs, ["Cursor", "Find", "Font", "Formatting", "Diff Editor", "Multi-File Diff Editor", "Minimap", "Suggestions", "Files"]);
        let ext: Vec<&str> = tree.children[8].children.iter().map(|c| c.label.as_str()).collect();
        assert!(ext.contains(&"Git"), "{ext:?}");
        // "98 workspace settings are not applied" in 1.145.2.
        assert_eq!(restricted_workspace_setting_count(), 98);
    }

    #[test]
    fn query_filters() {
        let q = Query::parse("font size");
        assert!(q.matches(find("editor.fontSize").unwrap(), &|_| false));
        assert!(!q.matches(find("files.autoSave").unwrap(), &|_| false));
        assert!(matches_words("format", "editor format on save", true));
        assert!(matches_words("edit format", "editor format on save", false));
        // "files.exclude" finds the files' exclude settings first (VS Code: 5).
        let order: Vec<usize> = (0..settings().len()).collect();
        let found: Vec<&str> = rank("files.exclude", &order).iter().map(|&i| settings()[i].key.as_str()).collect();
        assert_eq!(found[0], "files.exclude", "{found:?}");
        assert!(found.contains(&"files.watcherExclude") && found.contains(&"search.exclude"), "{found:?}");
        let m = Query::parse("@modified");
        assert!(m.matches(find("files.autoSave").unwrap(), &|k| k == "files.autoSave"));
        assert!(!m.matches(find("editor.fontSize").unwrap(), &|k| k == "files.autoSave"));
    }
}
